function result=m2_test_foc_long
root=fileparts(fileparts(mfilename('fullpath')));folder=fullfile(root,'docs/reports/m2_foc_fixed_point');m2_test_foc_types;cfg=evalin('base','FOC_Fixed_Config');m='PMLSM_FOC_FixedPoint';open_system(fullfile(root,'simulink模型',[m '.slx']));set_param(m,'IntegerOverflowMsg','error','IntegerSaturationMsg','error','ParameterOverflowMsg','error','FixptConstOverflowMsg','error');N=round(cfg.Ranges.verified_duration_s/cfg.Parameters.Ts_ACR)+1;u=zeros(N,9);u(:,6)=2^-cfg.Types.Current.FractionLength;u(:,9)=48;
out=m2_run_foc_sequence(m,u,true);state=double(out.logsout.get('x_q').Values.Data);step=double(fi(cfg.Coefficients.KiTs.quantized*u(1,6),cfg.Types.Work,cfg.Fimath));expected=(0:N-1)'*step;err=max(abs(state-expected));assert(err<1e-10&&state(end)>.04,'M2:SMALL_ERROR_INTEGRAL','长时微误差积分失效或递推不符。');
aw=double(out.logsout.get('du_q_z').Values.Data);assert(all(aw==0));names=getElementNames(out.logsout);for k=1:numel(names),v=out.logsout.get(names{k}).Values;assert(all(isfinite(double(v.Data(:)))));end
result=struct('pass',true,'duration_s',out.logsout.get('x_q').Values.Time(end),'samples',N,'error_input_A',u(1,6),'fixed_step_V',step,'final_integral_V',state(end),'recursion_max_V',err,'unexpected_numeric_overflow_or_saturation',0,'diagnostics','wrap/saturation/constant-overflow:error','zero_initial_state',true,'unlimited_duration_claim',false);save(fullfile(root,'.runtime/m2_20261024/D_long.mat'),'out','result','-v7.3');fid=fopen(fullfile(folder,'long_acceptance.json'),'w');fprintf(fid,'%s',jsonencode(result,PrettyPrint=true));fclose(fid);disp('M2_LONG_PASS');
end
